import {
  IsNotEmpty,
  IsOptional,
  IsString,
  IsUUID,
  Length,
} from 'class-validator';

export class CreateBalanceSheetDto {
  @IsUUID()
  companyId: string;

  @IsUUID()
  accountTypeId: string;

  @IsString()
  @IsNotEmpty()
  @Length(1, 150)
  description: string;

  // Rejected by the service: classification codes are generated by the backend.
  @IsOptional()
  @IsString()
  code?: string;
}
